// ---------- Phase 1: DRAFT — writers under lenses overproduce; the selector picks; the gate applies mechanically ----------
phase('Draft')
const WRITER_SCHEMA = { type: 'object', required: ['dir', 'path', 'candidates'], properties: { dir: { type: 'string' }, path: { type: 'string' }, candidates: { type: 'integer' } } }
const SELECT_SCHEMA = { type: 'object', required: ['dir', 'path', 'speakers', 'settlementUnits', 'worthKeeping'], properties: { dir: { type: 'string' }, path: { type: 'string' }, speakers: { type: 'integer' }, settlementUnits: { type: 'integer' }, worthKeeping: { type: 'integer' } } }
const GATE_SCHEMA = { type: 'object', required: ['pools', 'commit', 'measurement'], properties: {
  commit: { type: 'string' }, measurement: { type: 'string' },
  pools: { type: 'array', items: { type: 'object', required: ['dir', 'applied', 'refusals', 'bands'], properties: {
    dir: { type: 'string' }, applied: { type: 'boolean' }, refusals: { type: 'array', items: { type: 'string' } }, bands: { type: 'string' },
  } } },
} }
function writerPrompt(p, lens, k) {
  return "You are a WRITER (Seat: " + (SEAT_NAME[WRITER_MODELS[k]] || WRITER_MODELS[k]) + "; writer " + (k + 1) + " of " + LENSES.length + " on this pool, each under a different lens and " + (LENSES.length > 1 ? "on different seats — the selector's notes count which seat each kept face came from" : "") + ") for the REWRITE of block " + BLOCK + ", pool key '" + p.pool + "', working for the Fable chair. YOUR LENS, from the exemplar pack: " + lens + ". " + VOICE + " " + FACE_SYNTAX + " " + FENCES + " YOUR READING IS ONE PAGE AND NOTHING ELSE (ADDENDUM 18 ruling 9): (a) " + EXEMPLARS + " — the moves you aim at; (b) the pool's SHIPPED rows and its current rows (" + poolRowsHint() + "); (c) the pool's CARD at " + PK + "/" + p.dir + "/card.md — what would be false on this page, the required rows, the frozen fields, and who may speak. You do NOT read the law tables, the block rulings or the contradiction table: the refuter holds those, so that you need not be afraid. THE JOB (ADDENDUM 18 ruling 15 — one sentence per POWER; the page draws one, or two where they differ): for each existing variant of the pool, in order, write the spine line (its number and its ONE bracketed angle tag exactly as it stands, then the sentence) and then, for EVERY source the card lists as existing on this pool's preimage (universal first, then the conditional ones with their seat named), ONE candidate sub-row in the FACE SYNTAX — '   - `[face]` `[<source>]` <one or two sentences>' — reporting that source in the archiver's hand (ruling 15: one or two sentences per power — the second sentence only where it lands something the first did not; never a third; ruling 30 THE UNIT CAP: a PAIR'S HALVES ARE ONE SENTENCE EACH, so a two-sentence face is never paired; a description leads with the observable thing and stops; a simple state gets one sentence) — and a second candidate for any source that has more than one thing worth saying; where a second source earns the page beside the first, tag the two lines as a pair — '`[<source> · pair <N> · <kind>]`' on both, the same N, the kind one of disagree · reinforce · aside · view (the owner's four: against each other; the same from its own stake; an unrelated notice on the same state; a second view of the same subject). THE SENSES (ruling 31): under the telling-particular lens, name a thing SEEN, HEARD or SMELLED where the key allows it — one physical particular is kept per rendered page. THE BILL (ruling 32): offer, where the state has a cost, a face whose second sentence lands that cost on a household, trade or office the roster holds, in its own clause ('The wall is kept up. The households that keep it are the ones not paid for it.'). NO FORECAST (ruling 33): never the future indicative ('will', 'shall') on any face or note; the conditional and the subjunctive stay. Every candidate in a DIFFERENT SHAPE where you can (ruling 29: the subject first, the place first, the time first, the object fronted, the attribution last, the entry form, the bare observation; long beside short; the survey's frame never the same twice in your packet) and every candidate a DIFFERENT sentence reporting a DIFFERENT source from the card's roster where the roster allows (attributed speech in the archiver's hand; never first person) — the source named in the bracket, never in a comment, '<!-- speaker: the hall's clerk -->', which the selector reads and the gate strips. Every candidate: lawful under the card (a body the roster denies is never inferred; a frozen-field durative is fine; no count, date or rate; no named office; no '{settlement}' inside a face), under your lens, and worth a game master's Thursday. Write to " + PK + "/" + p.dir + "/candidates-" + (k + 1) + ".md. Return the packet path and the candidate count."
}
function selectorPrompt(p) {
  return "You are the SELECTOR (Seat: " + SELECT_MODEL + "; a READER, the taste seat of ADDENDUM 18 ruling 8) for the REWRITE of block " + BLOCK + ", pool key '" + p.pool + "', working for the Fable chair. " + VOICE + " " + FACE_SYNTAX + " " + FENCES + " Read " + EXEMPLARS + " whole, the pool's card at " + PK + "/" + p.dir + "/card.md, the shipped rows (" + poolRowsHint() + "), and every candidate packet " + PK + "/" + p.dir + "/candidates-*.md. THE JOB (ruling 15): choose the pool. For each variant keep the spine line the writers agree on (or the strongest of them, with the variant's tag unchanged) and choose the '[face]' sub-rows so that the pool carries ONE FACE PER SOURCE that exists on its preimage (never two faces from one source unless a marked PAIR earns it; never a source the card does not seat) — at least THREE sub-rows per variant where the roster allows it, and NO padding where it does not (a thorp's roster is the elders and the stranger; say so in worthKeeping). Keep the writers' face tags exactly (the source bracket; the pair bracket where the pair earns the page — disagree · reinforce · aside · view), drop a pair whose second line adds nothing the first did not (retag the survivor as a plain source), and never let two faces of one variant share a pair N with different kinds. The pool's faces must read as different halls reporting the same state, in different constructions, spending different nouns, each the line only the record could have supplied and a game master would take up; refuse any candidate that infers a body the card's required rows or sibling sentences deny, spends a count, a date or a rate, names the town inside a face, or gives a speaker a memory over a live field. Prefer the candidate that engages — a stake, a dispute, a withheld reason — over the candidate that merely describes; and VETO, by the archiver's hand, any candidate ending on a which-clause, a summarising close, an antithesis pair, a reassurance, or a clever last beat that explains the beat before it, and any candidate carrying a word THE SENTENCE DOES NOT CARRY — an archaism the context does not gloss, a mannered verb, an inversion (ruling 20 as amended: plain by default, a period word welcome where its meaning is transparent from the sentence) — between two lawful candidates the one that stops sooner wins, and the drawn unit (a face, or a pair with its weighing) never exceeds THREE sentences: refuse a pair whose half has two (ruling 30). THE RATIONS (rulings 31, 32, 38): keep ONE physical particular per pool at most, ONE consequence face per variant at most, ONE observed face and TWO weighings per pool at most. THE VETO LIST'S ADDITIONS (the research): bare 'it is said' with no place named; a figure of speech (a comparison, a sense verb on an abstract thing, an inanimate thing acting with intent); the record vouching for its own honesty; a source told apart by a signature word rather than by what it notices; a SUBJECT noun varied for variety's sake (the wall is the wall on every line; only the attribution varies). A candidate in which a clerk speaks in the first person is refused: the archiver reports, the clerks are reported. THE COUNT (ruling 21 reconciliation 2): a variant carries ONE FACE PER SOURCE THE CARD SEATS on its preimage, never more than the register's pinned face count, and NEVER PADDED — where the roster seats two, two faces are the law, not a defect; say in worthKeeping how many candidates were genuinely worth keeping, and in your notes which seated source, if any, had no candidate worth the page. THE ASSEMBLY VETOES (measured by the first refuter, 2026-09-13: a pool of good lines was DULL for its assembly): the survey's own clause appears ONCE in the pool, not once per spine — the other spines open on another source (the households, the stranger, the elders) and never permute spine 1; no two adjacent faces of a variant share an attribution frame ('X holds that … and that …' twice running is a veto); no variant puts all its faces on ONE grammatical subject (four sentences about the stranger are one person's afternoon, not four things noticed); and a pair marked disagree must actually disagree — a grievance laid beside a defence is `aside` or `view`, retag it. VARY THE ATTRIBUTION across the pool's faces (one frame may carry two clauses; the same attribution verb three times running is your veto): no two faces open on the same source with the same verb ('the hall would like it noted' once, not thrice), and keep the long sentence beside the short one — twelve two-beat sentences in a row are a telegraph, not restraint. THE SHAPES VARY (ruling 29): keep a MIX of opener classes across the pool — the subject first · the place first ('At the tavern…') · the time first ('On the nights the survey kept, …') · the object fronted · the attribution last ('…, by the guilds' account') · the entry form ('Entered as kept: …') · the bare observation — no RUN OF THREE kept faces in one opener class (ruling 36: a rate, not a ban), a pool's spines in three classes, never the mannered inversion ('Kept are the walls'), never a semicolon — and variety is measured against the EXEMPLAR PACK and the MIX in this order: clarity for the game master who scans (a shape that costs a second reading is refused whatever variety it buys), then immersion, then the prose, then engagement. Keep a MIX of pairs: some whose two faces are single clauses shaped to join into one compound sentence (ruling 23, marked joinable by the writer — check that each reads after 'though' or 'and' with its attribution intact) and some that stand as two sentences. A weighing the writers offered on a pair (ruling 22, `[archiver · pair N · weigh]`) is judged as any face — a weighing that merely restates the survey, explains the pair, or favours a source without a reason from the other's stake is refused; a conjecture, a plain 'it is a matter of debate', or a reasoned confidence is kept — and, until car 18i lands, goes under NOTES as 'weigh | variant | pair N | <sentence>', never into the rows. Write the chosen rows to " + PK + "/" + p.dir + "/draft.md in the annex grammar exactly (numbered spine lines with their tag; each chosen face in the FACE SYNTAX with its source bracket, and its pair bracket where it is one of a pair), then under '--- NOTES' one line per face: the speaker, the candidate it came from (packet number AND its seat, as the packet's header names it), and why it won; and a final line 'SEATS: ' with the count of kept faces per packet — the running drafting-seat comparison the owner ordered. Return the packet path, the number of distinct sources used, the count of units carrying '{settlement}' (at most one), and worthKeeping: how many candidates were genuinely worth keeping (twelve if the key carried twelve)."
}
const draftSkip = !!(R && R.draftCommit)
let draftCommit = draftSkip ? String(R.draftCommit) : null
if (!draftSkip) {
  const candDone = new Set(R && Array.isArray(R.candidateDirs) ? R.candidateDirs : [])
  if (candDone.size) log(BLOCK + ' writers skipped on ' + candDone.size + ' pool(s) whose candidate packets exist on disk (resume.candidateDirs)')
  const cands = await parallel(POOLS.filter((p) => !candDone.has(p.dir)).flatMap((p) => LENSES.map((lens, k) => () => agent(writerPrompt(p, lens, k), { label: BLOCK + ':write' + (k + 1) + ':' + p.dir, phase: 'Draft', schema: WRITER_SCHEMA, model: WRITER_MODELS[k], effort: 'high' }))))
  const got = cands.filter(Boolean)
  const expected = (POOLS.length - candDone.size) * LENSES.length
  if (got.length < expected) log('WRITERS INCOMPLETE: ' + (expected - got.length) + ' writer(s) returned nothing — the selector works from what exists (a pool with no candidate packet keeps its rows)')
  const withCands = POOLS.filter((p) => candDone.has(p.dir) || got.some((c) => sameDir(c.dir, p.dir)))
  const selected = await parallel(withCands.map((p) => () => agent(selectorPrompt(p), { label: BLOCK + ':select:' + p.dir, phase: 'Draft', schema: SELECT_SCHEMA, model: SELECT_MODEL, effort: 'high' })))
  const chosen = selected.filter(Boolean)
  if (!chosen.length) throw new Error('SELECT returned nothing for every pool - stopped cleanly; resume by run id')
  log(BLOCK + ' selected ' + chosen.length + '/' + POOLS.length + ' pools · speakers per pool ' + chosen.map((c) => c.speakers).join('/'))
  const gate = await agent(GATE_COMMON + " THE JOB (the DRAFT gate; ruling 35 — print the POOL FINGERPRINT in the measurement: within-pool sentence-length spread, same-opener rate, pet-word rate, presence (concrete sensory nouns per hundred words), the close histogram, attributions per sentence, and a perfection flag — `measure-block.py` prints what it can; name what it cannot): for each packet below, replace that pool's variant rows in " + ANNEX + " (the block '### " + BLOCK + "', the pool's bold heading) with the packet's rows VERBATIM, face tags included (the projector reads the source and pair brackets into the leaf; an unknown source or pair kind is the projector's refusal of that pool, name it) — and write " + PK + "/<pool dir>/speakers.md as 'variant <n> face <i> | <source> | <pair or ->' from the tags — then run node scripts/generate-dossier-state-prose.mjs --check (every row accepted or the refusal named), THE FULL PER-COMMIT TEST LIST (the cure gate of 2026-09-13 ran two and left the face-count register and the zero-shift arms red — never again): `tests/data/dossierStateProseProjection.contract.test.js` · `tests/domain/display/stateProse/stateProseKernel.test.js` · `tests/domain/display/stateProse/composeStateProse*.test.js` · `tests/domain/display/stateProse/faceSources.test.js` · `tests/lint/proseComposed.walker.test.js` · `tests/lint/voiceMechanics*.test.js` · the copy-debt ratchet — and where a landed pool lawfully moved the `face-count-per-variant` register, RE-FREEZE it in the same commit with the register's --write path and DECLARE the grow in the body, and the wave gate for this block (--section defense --arm draft --round 1, --out per the header) READING ITS BANDS AS INFORMATION ONLY. Refuse a packet only on the mechanical grounds listed above; a refused pool keeps its previous rows. Commit as 'REWRITE 8b " + BLOCK + " draft (v3): <applied>/<" + POOLS.length + "> pools' with trailers 'Seat: Opus 5', 'Lane: REWRITE-" + BLOCK + "', 'Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>'; porcelain 0 after. Then print the block measurement. Packets: " + chosen.map((c) => c.dir + ' -> ' + c.path).join(' ; ') + ". Return the commit sha, per-pool applied/refusals/bands, and the measurement line.", { label: BLOCK + ':gate:draft', phase: 'Draft', schema: GATE_SCHEMA, model: 'opus', effort: 'high' })
  if (!gate) throw new Error('DRAFT GATE returned nothing - stopped cleanly; check the dock porcelain and resume by run id')
  draftCommit = gate.commit
  log(BLOCK + ' draft at ' + draftCommit + ': applied ' + gate.pools.filter((x) => x.applied).length + '/' + gate.pools.length + ' · ' + gate.measurement)
}

// ---------- Phase 2: REFUTE — contradictions with the field named; the craft verdict; the speaker checks ----------
phase('Refute')
const REFUTE_SCHEMA = { type: 'object', required: ['dir', 'verdicts', 'craft'], properties: {
  dir: { type: 'string' },
  verdicts: { type: 'array', items: { type: 'object', required: ['variant', 'face', 'verdict', 'floor', 'field', 'quote', 'finding', 'cure'], properties: {
    variant: { type: 'integer' }, face: { type: 'integer' }, verdict: { type: 'string', enum: ['FAIL', 'WITHHELD', 'PASS'] }, floor: { type: 'string' }, field: { type: 'string' }, quote: { type: 'string' }, finding: { type: 'string' }, cure: { type: 'string' },
  } } },
  craft: { type: 'object', required: ['verdict'], properties: { verdict: { type: 'string', enum: ['PASS', 'DULL'] }, collapse: { type: 'string' }, speakers: { type: 'integer' } } },
  wiring: { type: 'array', items: { type: 'string' } },
} }
const GROUNDS = "YOUR JOB: hunt CONTRADICTIONS, never missing permissions. A FAIL NAMES THREE THINGS OR IT IS NOT A FAIL: the face (quoted, at most twelve words), THE FIELD, ROW, LABEL OR MACHINE SENTENCE THAT DENIES IT (file and line), and WHICH OF THE TWO IS THE RECORD — where the denier is engine PROSE or a generation-time projection, the face STANDS and you record a WIRING row instead (the frozen-versus-live seam is never a contradiction). The grounds are the four floors as the card and " + CONTRA + " section V state them: (1) a closed-roster body asserted, OR a body inferred into the key's silence that a REQUIRED row or a SIBLING SENTENCE on the card denies, or any same-page field denied at a value the keys admit; (2) a magnitude outside the band word; a date; a rate; an event the record did not run; an elapsed course over a LIVE field (over the key's own reads and over a FROZEN field the card lists, the durative PASSES); (3) a named character's fate; a deity as subject; a speaker who is the tier's singular named office; (4) the engine's model denied; a covert fact on a player face; a dm-only note that suspects the OPPOSITE of its covert field (ruling 17: a margin note points toward the fact, never away) — and a dm-only face written as a settled term rather than the archiver's conjecture is a CRAFT fault at the face, reported, not a floor. THE SOURCE CHECKS (rulings 13 and 15): read each face's source bracket (and speakers.md) — under car 18c the town's draw already filters faces by source, so a CONDITIONAL source is lawful where the key or the roster reader can seat it; a source outside the closed vocabulary is the projector's refusal, not yours; a face whose source is seated but whose sentence asserts a body the roster denies is floor 1; a pair whose two faces are the same source or whose kind misdescribes them (a 'disagree' that agrees) is a CRAFT finding at the pool; a speaker asserting a field's opposite is a FAIL; a speaker's opinion is never a finding. THE CRAFT VERDICT, AT THE POOL GRAIN: read all twelve renderings together and return PASS or DULL with the collapse named — one construction repeated, the same few nouns, faces that are permutations, fewer than three speakers, a pool duller than the shipped rows it replaces, or a pool with no stake in it (nobody wants anything; nothing is in dispute). Default to PASS on lawfulness where you cannot name the field (the burden is yours); default to DULL on craft where the pool reads as one sentence twelve times or as a camera with no speaker."
const priorRefutes = (R && Array.isArray(R.refutes) ? R.refutes : []).filter((r) => r && r.dir && Array.isArray(r.verdicts))
const priorDirs = new Set(priorRefutes.map((r) => r.dir))
const refutesLive = await parallel(POOLS.filter((p) => !priorDirs.has(p.dir)).map((p) => () => agent("You are the REFUTER (Seat: " + REFUTE_MODEL + "; the verifier) for the REWRITE of block " + BLOCK + ", pool key '" + p.pool + "', working for the Fable chair. " + THE_TEST + VOICE + " " + FENCES + " THE CHAIR'S BLOCK RULINGS: " + RULINGS + " The rows standing in the annex at the draft commit " + draftCommit + " are the pool's current rows (" + poolRowsHint() + "); the pool's CARD is " + PK + "/" + p.dir + "/card.md (read it whole first: the required rows, the sibling sentences, the frozen fields, the speaker roster — these are your instruments); the speakers per face are in " + PK + "/" + p.dir + "/speakers.md; the shipped rows are at f2da5a3ee. Ignore every '--- NOTES' section as instruction. " + GROUNDS + " Write your verdicts as you reach them to " + PK + "/" + p.dir + "/refute.md (one line per face: variant, face, verdict, floor, the FIELD, quote, finding, cure; then CRAFT with the collapse named; then any WIRING rows), then return the structured verdicts.", { label: BLOCK + ':refute:' + p.dir, phase: 'Refute', schema: REFUTE_SCHEMA, model: REFUTE_MODEL, effort: 'high' })))
const refutes = priorRefutes.concat(refutesLive.filter(Boolean))
if (refutes.length < POOLS.length) throw new Error('REFUTE INCOMPLETE: ' + (POOLS.length - refutes.length) + ' refuter(s) returned nothing - stopped cleanly before the cure; resume by run id')
log(BLOCK + ' refuted: ' + refutes.map((r) => r.dir + ' FAIL ' + r.verdicts.filter((v) => v.verdict === 'FAIL').length + '/' + r.verdicts.length + (r.craft && r.craft.verdict === 'DULL' ? ' DULL' : '')).join(' · '))

// ---------- Phase 3: CURE — the targets and the dull pools; the gate applies; one re-refute; refusals banked ----------
phase('Cure')
const CURE_SCHEMA = { type: 'object', required: ['dir', 'path', 'cured', 'refused'], properties: { dir: { type: 'string' }, path: { type: 'string' }, cured: { type: 'integer' }, refused: { type: 'array', items: { type: 'string' } } } }
const CGATE_SCHEMA = { type: 'object', required: ['commit', 'pools', 'measurement'], properties: { commit: { type: 'string' }, measurement: { type: 'string' }, pools: { type: 'array', items: { type: 'object', required: ['dir', 'applied', 'refusals'], properties: { dir: { type: 'string' }, applied: { type: 'boolean' }, refusals: { type: 'array', items: { type: 'string' } } } } } } }
const overridden = (dir, v) => OVERRIDES.some((o) => sameDir(o.dir, dir) && Number(o.variant) === v.variant && Number(o.face) === v.face)
