if (live.length && !cureCommit) {
  log(BLOCK + ' cure: ' + live.length + ' pool(s), ' + live.reduce((n, s) => n + s.targets.length, 0) + ' target(s), ' + live.filter((s) => s.dull).length + ' dull')
  const packets = await parallel(live.map((s) => () => agent("You are the CURER (Seat: " + CURE_MODEL + "; a different author from the writers) for the REWRITE of block " + BLOCK + ", pool key '" + s.p.pool + "', working for the Fable chair. " + VOICE + " " + FENCES + " YOUR READING: " + EXEMPLARS + ", the pool's card " + PK + "/" + s.p.dir + "/card.md, the rows standing at HEAD (" + head + "; " + poolRowsHint() + "), the speakers " + PK + "/" + s.p.dir + "/speakers.md, and the refuter's packet " + PK + "/" + s.p.dir + "/refute.md. THE TARGETS: " + s.targets.map((t) => 'variant ' + t.variant + ' face ' + t.face + ' | ' + t.quote + ' | ' + t.finding + ' | cure: ' + t.cure).join(' ;; ') + ". " + (s.dull ? "⭐ THIS POOL IS RULED DULL: '" + s.dull + "'. Rewrite EVERY face of EVERY variant (the byte-identical rule is lifted): give the pool at least three speakers with stakes, twelve different sentences, and something in dispute. " : "Change ONLY the targeted faces; every other face stays BYTE-IDENTICAL (the gate diffs them). ") + "THE JOB: write " + PK + "/" + s.p.dir + "/cure.md as the pool's complete rows in the annex grammar (each face keeps or gains its source bracket in the FACE SYNTAX). For each target cure the finding named and nothing else; a target you cannot cure lawfully stays as it is and is listed under --- NOTES. Return the packet path, the count cured, the refused targets.", { label: BLOCK + ':cure:' + s.p.dir, phase: 'Cure', schema: CURE_SCHEMA, model: CURE_MODEL, effort: 'high' }).then((r) => r && ({ s, r }))))
  const got = packets.filter(Boolean)
  if (!got.length) throw new Error('CURE returned nothing for every pool - stopped cleanly; resume by run id')
  const cgate = await agent(GATE_COMMON + " THE JOB (the CURE gate; HEAD must be " + head + "): for each packet, FIRST diff its rows against the pool's rows at HEAD face by face: a non-target face that differs by one byte REFUSES the packet (name the face) — EXCEPT for the DULL pools (" + (live.filter((x) => x.dull).map((x) => x.p.dir).join(', ') || 'none') + "), where every face may differ and you check only the mechanical shape. Apply accepted packets verbatim, tags included (rewrite speakers.md from the tags as before), run the projector --check, THE FULL PER-COMMIT TEST LIST (the cure gate of 2026-09-13 ran two and left the face-count register and the zero-shift arms red — never again): `tests/data/dossierStateProseProjection.contract.test.js` · `tests/domain/display/stateProse/stateProseKernel.test.js` · `tests/domain/display/stateProse/composeStateProse*.test.js` · `tests/domain/display/stateProse/faceSources.test.js` · `tests/lint/proseComposed.walker.test.js` · `tests/lint/voiceMechanics*.test.js` · the copy-debt ratchet — and where a landed pool lawfully moved the `face-count-per-variant` register, RE-FREEZE it in the same commit with the register's --write path and DECLARE the grow in the body and the wave gate (--section defense --arm cure --round 1, --out per the header; bands as information), commit as 'REWRITE 8b " + BLOCK + " cure (v3): <applied>/<" + got.length + "> pools' with the trailers; porcelain 0 after; print the block measurement. Targets per pool: " + got.map((x) => x.s.p.dir + ': ' + x.s.targets.map((t) => 'v' + t.variant + 'f' + t.face).join(',')).join(' ; ') + ". Packets: " + got.map((x) => x.s.p.dir + ' -> ' + x.r.path).join(' ; ') + ". Return the commit sha, per-pool applied/refusals, and the measurement.", { label: BLOCK + ':gate:cure', phase: 'Cure', schema: CGATE_SCHEMA, model: 'opus', effort: 'high' })
  if (!cgate) throw new Error('CURE GATE returned nothing - stopped cleanly; resume by run id')
  cureCommit = cgate.commit; head = cureCommit
  const appliedSet = new Set(cgate.pools.filter((x) => x.applied).map((x) => dirKey(x.dir)))   // the gate returns the ABSOLUTE dir; wf_fef9717d-ad4 skipped the re-refute on `appliedSet.has(dirKey(s.p.dir))`
  const rerefutes = await parallel(live.filter((s) => appliedSet.has(dirKey(s.p.dir))).map((s) => () => agent("You are the REFUTER (Seat: " + REFUTE_MODEL + ") for the CURE of block " + BLOCK + ", pool key '" + s.p.pool + "'. " + THE_TEST + VOICE + " " + FENCES + " THE CHAIR'S BLOCK RULINGS: " + RULINGS + " RULING 35: read the pool's FINGERPRINT in the gate's measurement BEFORE you vote PASS or DULL, and quote the figure that moved you; and read the card's SIBLING RUNGS — a face that reads as the neighbouring rung of its key is a floor-1 finding against the key's own state. The rows at HEAD " + head + " are the cured pool (" + poolRowsHint() + "); the card is " + PK + "/" + s.p.dir + "/card.md; the speakers " + PK + "/" + s.p.dir + "/speakers.md; the curer's packet " + PK + "/" + s.p.dir + "/cure.md (its notes are claims to test). THE CURED FACES: " + s.targets.map((t) => 'v' + t.variant + 'f' + t.face + ' | ' + t.finding).join(' ;; ') + (s.dull ? " AND THE WHOLE POOL (it was DULL: '" + s.dull + "')" : "") + ". " + GROUNDS + " Refute every cured face (and, for a dull pool, every face and the craft verdict again). Write to " + PK + "/" + s.p.dir + "/rerefute.md, then return the structured verdicts.", { label: BLOCK + ':rerefute:' + s.p.dir, phase: 'Cure', schema: REFUTE_SCHEMA, model: REFUTE_MODEL, effort: 'high' }).then((r) => r && ({ s, r }))))
  for (const s of live) {
    const x = rerefutes.find((y) => y && y.s && sameDir(y.s.p.dir, s.p.dir))
    if (!appliedSet.has(dirKey(s.p.dir))) { s.history.push('cure packet refused by the gate; targets stand as face refusal rows'); continue }
    if (!x) { s.history.push('re-refuter returned nothing; targets carried, reported'); continue }
    const fails = x.r.verdicts.filter((v) => v.verdict === 'FAIL' && !overridden(s.p.dir, v))
    s.history.push('re-refuted: FAIL ' + fails.length + ' · craft ' + (x.r.craft ? x.r.craft.verdict : '-'))
    s.targets = fails.map((v) => ({ variant: v.variant, face: v.face, quote: v.quote, finding: v.finding + ' [' + v.floor + ': ' + v.field + ']', cure: v.cure }))
    s.dull = x.r.craft && x.r.craft.verdict === 'DULL' ? String(x.r.craft.collapse) : null
  }
}
const refusalRows = open.flatMap((s) => s.targets.map((t) => s.p.dir + ' | variant ' + t.variant + ' | face ' + t.face + ' | ' + t.finding))
const dullLeft = open.filter((s) => s.dull).map((s) => s.p.dir + ' | ' + s.dull)
log(BLOCK + ' done at ' + head + ': face refusal rows ' + refusalRows.length + ' · pools still dull ' + dullLeft.length)

return {
  block: BLOCK, dock: DOCK, draftCommit, cureCommit, head,
  refutes: refutes.map((r) => ({ dir: r.dir, fail: r.verdicts.filter((v) => v.verdict === 'FAIL').length, withheld: r.verdicts.filter((v) => v.verdict === 'WITHHELD').length, pass: r.verdicts.filter((v) => v.verdict === 'PASS').length, craft: r.craft ? r.craft.verdict : null, speakers: r.craft ? r.craft.speakers : null })),
  cure: open.map((s) => ({ dir: s.p.dir, history: s.history, stillOpen: s.targets.length, dull: s.dull })),
  refusalRows, dullLeft,
  tokens: budget.spent(),
}
